    const int32_t col = tid + i * 256;
    held[i] -= mean;
    if (col < 1152) variance += held[i] * held[i];
  }
#pragma unroll
  for (int32_t offset = 16; offset > 0; offset >>= 1)
    variance += __shfl_xor_sync(0xffffffffu, variance, offset);
